void dfs(int u, int p, vector<vector<pair<int,int>>> &g, vector<int> &pref)
{
    for(auto [v,parity]:g[u])
    {
        if(v==p)continue;
        pref[v]=pref[u]^parity;
        dfs(v,u,g,pref);
    }
}
void solve() {
    int n;
    cin>>n;
    vector<vector<pair<int,int>>> g(n+1);
    vector<int> p(n+1);
    string s;
    for(int i=2;i<=n;i++)
    {
        int f=0;
        if(i%2)f=1;
        int l=n;
        if((i%2)!=(l%2))l--;
        if(i-f>l-i)
        {
            cout<<"? "<<f+1<<" "<<i<<"\n";
            cout.flush();
            int x;
            cin>>x;
            int par=((i-f)/x)%2;
            g[i].push_back({f,par});
            g[f].push_back({i,par});
        }
        else
        {
            cout<<"? "<<i+1<<" "<<l<<"\n";
            cout.flush();
            int x;
            cin>>x;
            int par=((l-i)/x)%2;
            g[i].push_back({l,par});
            g[l].push_back({i,par});
        }
    }
    p[1]=0;
    dfs(0,-1,g,p);
    dfs(1,-1,g,p);

    for(int i=1;i<=n;i++)
    {
        int r=p[i]^p[i-1];
        if(r==0)s+='0';
        else s+='1';
    }
    cout<<"! "<<s<<"\n";
    cout.flush();
    int w;
    cin>>w;
    if(w)return;

    for(int i=0;i<n;i++)
    {
        if(s[i]=='0')s[i]='1';
        else s[i]='0';
    }
    cout<<"! "<<s<<"\n";
    cout.flush();
    cin>>w;
}

