struct FenwickTree{
    int n;
    vector <int> f;
    vector <int> b;

    inline void add(int i, int x){
        b[i] += x;
        for (int j = i; j <= n; j += j & (-j)){
            f[j] += x;
        }
    }

    inline void modify(int i, int x){
        add(i, x - b[i]);
    }

    inline void init(int nn, vector <int> a){
        n = nn;
        if (a.size() == n){
            vector <int> a2;
            a2.push_back(0);
            for (auto x : a) a2.push_back(x);
            a = a2;
        }

        f.resize(n + 1);
        b.resize(n + 1);

        for (int i = 0; i <= n; i++) f[i] = 0, b[i] = 0;

        for (int i = 1; i <= n; i++){
            modify(i, a[i]);
        }
    }

    inline int query(int x){
        int ans = 0;
        for (int i = x; i; i -= i & (-i)){
            ans += f[i];
        }
        return ans;
    }

    inline int query(int l, int r){
        return query(r) - query(l - 1);
    }
};

void Solve() 
{
    // make edges l -> nx[l] 
    // binary lifting 
    // cost(i) needs to be computed 
    // sequence length > prefix => balances at (seq + prefix) / 2 
    // otherwise balances at seq length * prefix 
    // the first can happen only log times 
    // for all active i, need to add (i - l) * val[i] 
    // fix the sum for i = l and i such that sequence length > prefix 
    // find first val[i] > current, is it guaranteed to be active?

    int n, q; cin >> n >> q;

    vector <int> p(n + 1);
    for (int i = 1; i <= n; i++){
        cin >> p[i];
    }

    vector<vector<pair<int, int>>> adj(n + 1);
    for (int i = 1; i <= q; i++){
        int l, r; cin >> l >> r;

        adj[l].push_back({r, i});
    }

    vector <int> nxs(n + 1, n + 1);
    {
        stack <pair<int, int>> st;
        for (int i = 1; i <= n; i++){
            while (!st.empty() && st.top().first > p[i]){
                nxs[st.top().second] = i;
                st.pop();
            }

            st.push({p[i], i});
        }
    }

    vector<vector<int>> jump(21, vector<int>(n + 2));
    for (int i = 1; i <= n + 1; i++){
        jump[0][i] = (i > n) ? i : nxs[i];
    }

    for (int i = 1; i <= 20; i++){
        for (int j = 1; j <= n + 1; j++){
            jump[i][j] = jump[i - 1][jump[i - 1][j]];
        }
    }

    vector <int> val(n + 1);
    for (int i = 1; i <= n; i++){
        val[i] = nxs[i] - i;
    }

    // fenwick for i * val[i] and val[i]
    stack <pair<int, int>> st; // stack for active values 
    FenwickTree f1, f2;
    vector <int> vv(n);
    f1.init(n, vv); f2.init(n, vv);

    for (int i = 1; i <= n; i++){
        f1.modify(i, val[i]);
        f2.modify(i, val[i] * i);
    }

    set <int> ss;

    vector<vector<int>> at(n + 1);
    for (int i = 1; i <= n; i++){
        int r = i - val[i];
        if (r >= 1){
            at[r].push_back(i);
        }
    }

    auto deac = [&](int x){
        ss.erase(x);
        f1.modify(x, 0);
        f2.modify(x, 0);
    };

    vector <int> ans(q + 1);

    for (int l = n; l >= 1; l--){
        while (!st.empty() && st.top().first > p[l]){
            deac(st.top().second);
            st.pop();
        }
        st.push({p[l], l});
        ss.insert(l);
        for (auto x : at[l]){
            ss.erase(x);
        }

        for (auto [r, i] : adj[l]){
            ans[i] += f2.query(l, r) - l * f1.query(l, r);

            auto calc = [&](int x){
            //    cout << "UPD " << x << "\n";
                int vv = min(val[x], r - x + 1);
                if (x == l) vv--;
                if (vv > x - l){
                    vv += (x - l);
                    ans[i] += (vv / 2) * ((vv + 1) / 2);
                } else {
                    ans[i] += vv * (x - l);
                }
            };

            int pos = l;
            // while (pos <= r){
            //     if (nxs[pos] > r && val[pos] <= (pos - l)){
            //         ans[i] -= val[pos] * (pos - l);
            //         calc(pos);
            //     }
            //     pos = nxs[pos];
            // }
            for (int j = 20; j >= 0; j--){
                if (jump[j][pos] <= r){
                    pos = jump[j][pos];
                }
            }
            assert(nxs[pos] > r);
            if (!ss.count(pos)){
                ans[i] -= val[pos] * (pos - l);
                calc(pos);
            }

            for (auto x : ss){
                if (x <= r){
                    ans[i] -= val[x] * (x - l);
                    calc(x);
                } else {
                    break;
                }
            }
        }
    }

    for (int i = 1; i <= q; i++){
        cout << ans[i] << "\n";
    }
}

